import java.util.Scanner;

public class Main {
    static long[] arr = new long[30];

    static long computeMin(long n) {
        if (n <= 6) return n;
        long res1 = (long) 1e9, res2 = (long) 1e9;
        for (int i = 0; i < 20; i++) {
            if (arr[i] > n) {
                res1 = computeMin(n % arr[i - 1]) + i * (n / arr[i - 1]);
                break;
            }
        }
        for (int i = 0; i < 20; i++) {
            if (arr[i] >= n) {
                if (arr[i] - n >= n) res1 = (long) 1e9;
                else res2 = computeMin(arr[i] - n) + (i + 1);
                break;
            }
        }
        return Math.min(res1, res2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        arr[0] = 1;
        for (int i = 1; i < 18; i++) {
            arr[i] = arr[i - 1] * 10 + 1;
        }
        long input = scanner.nextLong();
        System.out.println(computeMin(input));
        scanner.close();
    }
}

